import csv,math,collections
up=collections.defaultdict(list);dn=collections.defaultdict(list)
for r in csv.DictReader(open('responses.csv')):
    s=[int(x) for x in r['number_set'].split(',')];t=int(r['target']);y=int(r['rating'])
    if t>max(s): up[min(int(math.log(t/max(s))/0.25),8)].append(y)
    elif t<min(s): dn[min(int(math.log(min(s)/t)/0.25),8)].append(y)
for k in range(9): print(k*0.25, len(up[k]), round(sum(up[k])/max(1,len(up[k])),2), len(dn[k]), round(sum(dn[k])/max(1,len(dn[k])),2))
"

